def priority(task, state, m=3.0, a=1.0, b=0.1, c=0.5):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    tier = m if task.tenant == 'premium' else 1.0
    wait = state.now - task.release
    late = max(0.0, -slack)
    if late <= 0.0:
        w = 1.0
    elif late <= 0.25 * est:
        w = 3.0
    elif late <= est:
        w = 10.0
    else:
        return -1e6 + a * wait / est
    pressure = state.queue_work / max(state.capacity * state.mean_est, 1e-6)
    return - (slack / est) * tier * w + a * wait / est + b * pressure * (tier / est)  # tuned (m=0.881,a=0.394,b=0.0481,c=0.34)

import math
def priority(task, state, k=1.0, m=3.0, a=2.0, b=4.0, c=10.0, fit_bonus=2.0, alpha=0.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    slack = task.due - p - state.now
    L = max(0.0, -slack)
    if L <= 0.0:
        pen = 1.0
    elif L <= 0.25 * p:
        pen = a
    elif L <= p:
        pen = b
    else:
        pen = c
    tier = m if task.tenant == 'premium' else 1.0
    fit = fit_bonus if r <= state.free else 1.0
    due_time = max(0.0, task.due - state.now)
    scale = max(k * max(state.mean_est, 1e-6), 1e-6)
    den = max(p * (r ** alpha), 1e-6)
    return tier * pen * fit * task.weight / den * math.exp(-due_time / scale)  # tuned (k=0.269,m=6.12,a=7.8,b=1.5,c=15.2,fit_bonus=5.97,alpha=0)

def priority(task, state, m=3.0, a1=1.0, a2=3.0, a3=10.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    slack = task.due - state.now - est
    lateness = max(0.0, -slack)
    if lateness <= 0.0:
        boost = 0.0
    elif lateness <= 0.25 * est:
        boost = a1
    elif lateness <= 1.0 * est:
        boost = a2
    else:
        boost = a3
    return (tier / est) * (1.0 + boost)  # tuned (m=1.34,a1=0.772,a2=1.18,a3=3.05)

def priority(task, state, a=0.25, b=1.0, m=3.0, alpha=0.1, beta=1.0, doomed_penalty=1e6):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    due = task.due
    tier = m if task.tenant == 'premium' else 1.0
    d0 = due - est
    d1 = due - (1.0 - a) * est
    d2 = due - (1.0 - b) * est
    if now <= d0:
        deadline = d0
    elif now <= d1:
        deadline = d1
    elif now <= d2:
        deadline = d2
    else:
        deadline = due + doomed_penalty
    return -deadline + beta * tier - alpha * est  # tuned (a=0.126,b=0.755,m=1.71,alpha=0.298,beta=0.885,doomed_penalty=6.64e+05)

import math
def priority(task, state, k=2.0, p=3.0, a=1.0, q=1e6):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    due = task.due
    if now <= due - est:
        target = due - est
        val = 1.0
    elif now <= due - 0.75 * est:
        target = due - 0.75 * est
        val = 3.0
    elif now <= due:
        target = due
        val = 10.0
    else:
        return -q + 1.0 / est
    if task.tenant == 'premium':
        val *= p
    slack = max(0.0, target - now)
    return -target + a * val * math.exp(-slack / (k * max(state.mean_est, 1e-6)))  # tuned (k=2.11,p=5.09,a=0.282,q=5.15e+05)

import math
def priority(task, state, k=0.5, m=3.0, c=1.0):
    est = max(task.estimated_runtime, 1e-6)
    mean_est = max(state.mean_est, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    base = task.weight / est * math.exp(-slack / (k * mean_est))
    if task.tenant == 'premium' and slack < c * est:
        base *= m
    return base  # tuned (k=0.453,m=10.9,c=0.367)

import math
def priority(task, state, m=3.0, mh=1.0, k=1.0, c=0.25, d=1.0, a1=1.5, a2=2.5, h=0.35, b=0.5, p=1.0, w=0.0):
    e = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    now = state.now
    s0 = task.due - e - now
    s1 = task.due + c * e - e - now
    s2 = task.due + d * e - e - now
    scale = max(k * mean, 1e-6)
    if s0 >= 0.0:
        risk = math.exp(-s0 / scale)
    elif s1 >= 0.0:
        risk = a1 * math.exp(-s1 / scale)
    elif s2 >= 0.0:
        risk = a2 * math.exp(-s2 / scale)
    else:
        risk = h
    if task.tenant == 'premium':
        tier = m if s2 >= 0.0 else mh
    else:
        tier = 1.0
    wait = max(0.0, now - task.release)
    aging = 1.0 + b * wait / max(e, mean)
    return tier * risk * aging * (max(task.weight, 1e-6) ** w) / max(e ** p, 1e-6)  # tuned (m=4.4,mh=3.91,k=0.327,c=0.255,d=0.75,a1=0.664,a2=7.24,h=0.392,b=0.682,p=0.552,w=0)
